INSERT INTO repo_modules (module_id, name, module_no, description, module_sd_id, status) VALUES ('MOD_COURSE_011_M01', 'Determinate Structures', '1', 'Determinate Structures examines Truss and beam analysis within Structural Analysis I. Key technical concerns include Equilibrium, load path, internal force, structural determinacy, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_DETERMINATE_STRUCTURES', 'Active'), ('MOD_COURSE_011_M02', 'Deflections', '2', 'Deflections examines Moment-area theorem within Structural Analysis I. Key technical concerns include Curvature, integration, compatibility, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_DEFLECTIONS', 'Active'), ('MOD_COURSE_011_M03', 'Energy Methods', '3', 'Energy Methods examines Virtual work within Structural Analysis I. Key technical concerns include Equilibrium, compatibility, work-energy relations, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_ENERGY_METHODS', 'Active'), ('MOD_COURSE_011_M04', 'Influence Lines', '4', 'Influence Lines examines Influence-line construction within Structural Analysis I. Key technical concerns include Moving loads, structural response, position dependence, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_INFLUENCE_LINES', 'Active'), ('MOD_COURSE_011_M05', 'Indeterminate Structures', '5', 'Indeterminate Structures examines Slope-deflection within Structural Analysis I. Key technical concerns include Stiffness, compatibility, equilibrium, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_INDETERMINATE_STRUCTURES', 'Active'), ('MOD_COURSE_012_M01', 'Soil Classification', '1', 'Soil Classification examines Atterberg limits within Geotechnical Engineering. Key technical concerns include Consistency, plasticity, water-content dependence, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_SOIL_CLASSIFICATION', 'Active'), ('MOD_COURSE_012_M02', 'Permeability', '2', 'Permeability examines Darcy''s law within Geotechnical Engineering. Key technical concerns include Potential gradient, hydraulic conductivity, porous-media flow, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_PERMEABILITY', 'Active'), ('MOD_COURSE_012_M03', 'Consolidation', '3', 'Consolidation examines Consolidation settlement within Geotechnical Engineering. Key technical concerns include Defining mechanism/properties, governing conditions, assumptions and limitations, application/performance criteria for Consolidation settlement, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_CONSOLIDATION', 'Active'), ('MOD_COURSE_012_M04', 'Shear Strength', '4', 'Shear Strength examines Mohr-Coulomb failure criterion within Geotechnical Engineering. Key technical concerns include Shear strength, effective stress, friction, cohesion, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_SHEAR_STRENGTH', 'Active'), ('MOD_COURSE_012_M05', 'Earth Pressure', '5', 'Earth Pressure examines Lateral earth pressure within Geotechnical Engineering. Key technical concerns include Stress state, equilibrium, soil-structure interaction, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_EARTH_PRESSURE', 'Active'), ('MOD_COURSE_013_M01', 'Water Demand', '1', 'Water Demand examines Demand forecasting within Environmental Engineering. Key technical concerns include Defining mechanism/properties, governing conditions, assumptions and limitations, application/performance criteria for Demand forecasting, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_WATER_DEMAND', 'Active'), ('MOD_COURSE_013_M02', 'Water Treatment', '2', 'Water Treatment examines Filtration within Environmental Engineering. Key technical concerns include Particle removal, hydraulic resistance, treatment performance, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_WATER_TREATMENT', 'Active'), ('MOD_COURSE_013_M03', 'Wastewater Collection', '3', 'Wastewater Collection examines Sewer design within Environmental Engineering. Key technical concerns include Public health, hydraulic capacity, reliability, gravity flow, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_WASTEWATER_COLLECTION', 'Active'), ('MOD_COURSE_013_M04', 'Sewage Treatment', '4', 'Sewage Treatment examines Activated sludge process within Environmental Engineering. Key technical concerns include Biological oxidation, mass balance, microbial growth, solids separation, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_SEWAGE_TREATMENT', 'Active'), ('MOD_COURSE_013_M05', 'Solid Waste', '5', 'Solid Waste examines Solid-waste management within Environmental Engineering. Key technical concerns include Waste hierarchy, pollution prevention, resource recovery, public health, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_SOLID_WASTE', 'Active'), ('MOD_COURSE_014_M01', 'Highway Planning', '1', 'Highway Planning examines Sight distance within Transportation Engineering. Key technical concerns include Safety, visibility, human factors, geometric design, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_HIGHWAY_PLANNING', 'Active'), ('MOD_COURSE_014_M02', 'Geometric Design', '2', 'Geometric Design examines Super elevation within Transportation Engineering. Key technical concerns include Lateral stability, drainage, geometric transition, safety, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_GEOMETRIC_DESIGN', 'Active'), ('MOD_COURSE_014_M03', 'Traffic Engineering', '3', 'Traffic Engineering examines Traffic flow and control within Transportation Engineering. Key technical concerns include Mobility, safety, capacity, accessibility, efficiency, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_TRAFFIC_ENGINEERING', 'Active'), ('MOD_COURSE_014_M04', 'Pavement Materials', '4', 'Pavement Materials examines Bitumen testing within Transportation Engineering. Key technical concerns include Material characterization, temperature dependence, quality control, durability, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_PAVEMENT_MATERIALS', 'Active'), ('MOD_COURSE_014_M05', 'Pavement Design', '5', 'Pavement Design examines Flexible pavement design within Transportation Engineering. Key technical concerns include Load distribution, durability, material efficiency, serviceability, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_PAVEMENT_DESIGN', 'Active'), ('MOD_COURSE_015_M01', 'Project Lifecycle', '1', 'Project Lifecycle examines Gantt charts within Construction Planning & Management. Key technical concerns include Sequencing, visibility, schedule control, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_PROJECT_LIFECYCLE', 'Active'), ('MOD_COURSE_015_M02', 'Network Techniques (CPM/PERT)', '2', 'Network Techniques (CPM/PERT) examines Crashing within Construction Planning & Management. Key technical concerns include Time-cost trade-off, critical-path focus, resource allocation, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_NETWORK_TECHNIQUES_CPM_PERT', 'Active'), ('MOD_COURSE_015_M03', 'Resource Allocation', '3', 'Resource Allocation examines Resource levelling within Construction Planning & Management. Key technical concerns include Resource constraints, feasibility, schedule stability, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_RESOURCE_ALLOCATION', 'Active'), ('MOD_COURSE_015_M04', 'Cost Control', '4', 'Cost Control examines Depreciation and cost control within Construction Planning & Management. Key technical concerns include Lifecycle costing, accounting allocation, budget control, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_COST_CONTROL', 'Active'), ('MOD_COURSE_015_M05', 'Construction Equipment', '5', 'Construction Equipment examines Equipment selection and productivity within Construction Planning & Management. Key technical concerns include Productivity, resource efficiency, safety, lifecycle economics, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_CONSTRUCTION_EQUIPMENT', 'Active'), ('MOD_COURSE_016_M01', 'Basics of Surveying', '1', 'Basics of Surveying examines Errors within Surveying & Geomatics. Key technical concerns include Measurement quality, uncertainty, repeatability, error propagation, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_BASICS_OF_SURVEYING', 'Active'), ('MOD_COURSE_016_M02', 'Leveling & Contouring', '2', 'Leveling & Contouring examines Benchmarks within Surveying & Geomatics. Key technical concerns include Reference frames, traceability, control, consistency, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_LEVELING_CONTOURING', 'Active'), ('MOD_COURSE_016_M03', 'Theodolite Surveying', '3', 'Theodolite Surveying examines Angular measurement within Surveying & Geomatics. Key technical concerns include Geometric reference, precision, redundancy, instrument calibration, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_THEODOLITE_SURVEYING', 'Active'), ('MOD_COURSE_016_M04', 'Curves', '4', 'Curves examines Horizontal and vertical curves within Surveying & Geomatics. Key technical concerns include Geometric continuity, safety, comfort, visibility, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_CURVES', 'Active'), ('MOD_COURSE_016_M05', 'Modern Surveying (GPS/GIS)', '5', 'Modern Surveying (GPS/GIS) examines GNSS/GPS and GIS applications within Surveying & Geomatics. Key technical concerns include Spatial reference, interoperability, positioning accuracy, spatial analysis, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_MODERN_SURVEYING_GPS_GIS', 'Active'), ('MOD_COURSE_017_M01', 'Basic Concepts', '1', 'Basic Concepts examines Control volumes within Engineering Thermodynamics. Key technical concerns include Defining mechanism/properties, governing conditions, assumptions and limitations, application/performance criteria for Control volumes, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_BASIC_CONCEPTS', 'Active'), ('MOD_COURSE_017_M02', 'First Law', '2', 'First Law examines Energy equation within Engineering Thermodynamics. Key technical concerns include Energy conservation, work/heat interactions, property accounting, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_FIRST_LAW', 'Active'), ('MOD_COURSE_017_M03', 'Second Law', '3', 'Second Law examines Second-law analysis within Engineering Thermodynamics. Key technical concerns include Entropy, irreversibility, directionality, maximum performance, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_SECOND_LAW', 'Active'), ('MOD_COURSE_017_M04', 'Entropy', '4', 'Entropy examines Entropy generation within Engineering Thermodynamics. Key technical concerns include Irreversibility, entropy production, lost work/exergy, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_ENTROPY', 'Active'), ('MOD_COURSE_017_M05', 'Gas Power Cycles', '5', 'Gas Power Cycles examines Carnot cycle within Engineering Thermodynamics. Key technical concerns include Reversibility, temperature limits, efficiency bound, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_GAS_POWER_CYCLES', 'Active'), ('MOD_COURSE_018_M01', 'Fluid Kinematics', '1', 'Fluid Kinematics examines Velocity and acceleration fields within Fluid Mechanics & Machinery. Key technical concerns include Kinematics, spatial gradients, material derivative, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_FLUID_KINEMATICS', 'Active'), ('MOD_COURSE_018_M02', 'Conservation Laws', '2', 'Conservation Laws examines Navier-Stokes equation within Fluid Mechanics & Machinery. Key technical concerns include Momentum conservation, constitutive modelling, viscosity, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_CONSERVATION_LAWS', 'Active'), ('MOD_COURSE_018_M03', 'Viscous Flow', '3', 'Viscous Flow examines Boundary layers within Fluid Mechanics & Machinery. Key technical concerns include Defining mechanism/properties, governing conditions, assumptions and limitations, application/performance criteria for Boundary layers, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_VISCOUS_FLOW', 'Active'), ('MOD_COURSE_018_M04', 'Hydraulic Turbines', '4', 'Hydraulic Turbines examines Pelton and Francis turbines within Fluid Mechanics & Machinery. Key technical concerns include Energy conversion, hydraulic efficiency, flow control, mechanical power, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_HYDRAULIC_TURBINES', 'Active'), ('MOD_COURSE_018_M05', 'Pumps', '5', 'Pumps examines Centrifugal pumps within Fluid Mechanics & Machinery. Key technical concerns include Defining mechanism/properties, governing conditions, assumptions and limitations, application/performance criteria for Centrifugal pumps, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_PUMPS', 'Active'), ('MOD_COURSE_019_M01', 'Mechanisms', '1', 'Mechanisms examines Grashof''s law within Kinematics of Machinery. Key technical concerns include Kinematic feasibility, link geometry, mobility, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_MECHANISMS', 'Active'), ('MOD_COURSE_019_M02', 'Velocity/Acceleration Analysis', '2', 'Velocity/Acceleration Analysis examines Instantaneous centers within Kinematics of Machinery. Key technical concerns include Relative kinematics, rigid-body motion, instantaneous rotation, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_VELOCITY_ACCELERATION_ANALYSIS', 'Active'), ('MOD_COURSE_019_M03', 'Cams', '3', 'Cams examines Cam displacement diagrams within Kinematics of Machinery. Key technical concerns include Prescribed motion, continuity, acceleration control, kinematics, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_CAMS', 'Active'), ('MOD_COURSE_019_M04', 'Gears', '4', 'Gears examines Epicyclic gear trains within Kinematics of Machinery. Key technical concerns include Relative rotation, velocity ratio, compact power transmission, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_GEARS', 'Active'), ('MOD_COURSE_019_M05', 'Friction', '5', 'Friction examines Friction in machine mechanisms within Kinematics of Machinery. Key technical concerns include Energy dissipation, contact mechanics, wear, efficiency, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_FRICTION', 'Active'), ('MOD_COURSE_020_M01', 'Conduction', '1', 'Conduction examines Fins within Heat and Mass Transfer. Key technical concerns include Conduction-convection coupling, thermal resistance, surface area, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_CONDUCTION', 'Active'), ('MOD_COURSE_020_M02', 'Convection', '2', 'Convection examines Free/forced convection within Heat and Mass Transfer. Key technical concerns include Convection, buoyancy, forced flow, boundary layers, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_CONVECTION', 'Active'), ('MOD_COURSE_020_M03', 'Radiation', '3', 'Radiation examines Blackbody radiation within Heat and Mass Transfer. Key technical concerns include Thermal radiation, emissive power, temperature dependence, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_RADIATION', 'Active'), ('MOD_COURSE_020_M04', 'Heat Exchangers', '4', 'Heat Exchangers examines Log Mean Temperature Difference (LMTD) within Heat and Mass Transfer. Key technical concerns include Defining mechanism/properties, governing conditions, assumptions and limitations, application/performance criteria for LMTD, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_HEAT_EXCHANGERS', 'Active'), ('MOD_COURSE_020_M05', 'Mass Transfer', '5', 'Mass Transfer examines Mass diffusion and transfer coefficients within Heat and Mass Transfer. Key technical concerns include Species conservation, diffusion, convection, mass-transfer resistance, with emphasis on how the contained topics are represented, analysed, and applied within their stated assumptions.', 'MSD_MASS_TRANSFER', 'Active') ON CONFLICT DO NOTHING;